NAME = 'NorSMB: Studentmållagsbibelen frå 1921'
BOOK = 'Joel'

CHAPTERS = {
    1: {
        1: 'Herrens ord som kom til Joel Petuelsson.',
        2: 'Gjev gaum åt dette, de som gamle er. Og lyd på det kvar som bur i landet! Hev sovore hendt i dykkar tid, eller i dykkar fedra-tid?',
        3: 'Fortel det til dykkar born, og dykkar born til sine born, og deira born til ei ætt som kjem!',
        4: 'Det som gnagaren leivde, åt grashoppen upp. Det som grashoppen leivde, åt bitaren upp. Det som bitaren leivde, åt etaren upp.',
        5: 'Vakna, de drukne, og gråte, jamra, vindrikkarar alle! For druvesafti er rivi dykk frå munn.',
        6: 'Eit folk hev fare yver landet mitt, veldugt og utan tal, med tenner som løvetenner, dei jakslar som løvor hev.',
        7: 'Vintrei mine er tynte og fiketre brotne ned, dei hev flekt deim reint og hivt deim, det heng kvite greiner på.',
        8: 'Klaga som ei møy som syrgjeklædd gjeng yver sin ungdoms brudgom.',
        9: 'Grjon- og drykkoffer er kvorvne frå Herrens hus, prestarne syrgjer, Herrens tenarar.',
        10: 'Åkrar er øydde, jordi jamrar. For øydt er kornet, vinsafti magtlaus, oljen er kvorven.',
        11: 'Bonden er magtstolen, vindyrkar rådlaus for kveite og bygg, grøda på marki er tynt.',
        12: 'Vintre er mergstolne, fiketre folna. Granattre og palma og apall, alle tre hev turka burt. Ja, fagnaden er stolen frå mannaheim.',
        13: 'Syrgjeklædde klage, de prestar! Jamra dykk, de som tener ved altaret! Gakk inn og vake syrgjeklædde, de min Guds tenarar! For burte frå dykkar Guds hus er grjon- og drykkoffer.',
        14: 'Lys ut fasta og heilag samling, få dei gamle i hop, ja alle som bur i landet, til Herren, dykkar Guds hus! Til Herren de ropa må.',
        15: 'Å hå for ein dag! Nær er Herrens dag. Som vald ifrå Allvald han kjem.',
        16: 'Strauk ikkje maten burt med me såg på, frå Guds hus gleda og frygd?',
        17: 'Kornet turkar burt under jordskorpa. Tome er buri, lødorne øydest. Ja, kornet turkar burt.',
        18: 'Kor buskapen rautar! Rådlaus er kvar bøling; for ikkje beite dei finn, sauerne jamvel lyt bøta.',
        19: 'Til deg, Herre, ropar eg. For elden han åt hamni på heidi, og logen leika i ved og i tre.',
        20: 'Jamvel dyri i marki etter deg mun stynja, for turre er bekkjefari. Og elden han åt hamni på heidi.',
    },
    2: {
        1: 'Lat luren ljoma på Sion! Skrik høgt på mitt heilage fjell! Skjelve, alle i mannaheimen! Koma skal Herrens dag, ja, han er nær.',
        2: 'Ein dag med myrker og dimma, ein dag med skodda og sky, som ein morgongråe er eit tallaust folk breidt yver fjelli. Du liken aldri ser frå æva som var, og aldri i åri til komande ætter.',
        3: 'Framfyre et elden upp; og etter kjem brennande logen. Som Edenshagen var landet framfyre og etterpå snaudaste heidi. Å berga noko nyttar ikkje her.',
        4: 'Som øykjer er dei å sjå til, som stridshestar tråvar dei fram.',
        5: 'Liksom glamrande vogner fer dei yver alle fjell. Det susar og brusar, som når eld sleikjer strå, som ei veldug herfylking samla til strid.',
        6: 'Støkken tek folk ved syni, alle andlit skiftar lit.',
        7: 'Som kjempor rusar dei i veg, liksom stridsmenner stormar dei murar. Kvar ein på si leid sturtar fram, og aldri dei krøkjer sin veg.',
        8: 'Ingen trengjer den andre burt, kvar hev si eigi braut, tvert gjenom våpni, og ho brest ikkje rekkja.',
        9: 'Inn i byen dei stormar, stig upp på muren, gjeng inn i husi, og inn gjenom vindaugo bryt dei seg som tjuvar.',
        10: 'Jordi fyre deim skjelv, himlarne bivrar, sol og måne dei svartnar, medan stjernorne løyner sin glans.',
        11: 'Og Herren let høyra sitt mål framfyre si fylking, for ovstor er hans herlæger, veldug hans ærendsvein er. Ja, stor er Herrens dag og skræmeleg, kven held honom ut?',
        12: 'Men no og det gjeld, so mæler Herren, vend um til meg med heile dykkar hjarta, med fasta og gråt og med klaga.',
        13: 'Riv sund dykkar hjarta og ei dykkar klæde, vend um til Herren dykkar Gud! For han er nådig og hugmild er han, hev tolugt sinn, er rik på miskunn, han angrar det vonde.',
        14: 'Ja, kven veit? Han snur og angrar, og han legg etter seg velsigning, grjon- og drykkoffer for Herren, dykkar Gud.',
        15: 'Blås i luren på Sion, haldt fastehelg, lys heilag samling!',
        16: 'Samla folket! Vigsle lyden! Få i hop dei gamle, samla dei små, ja, borni på fanget! Brudgomen gange or sitt hus og bruri frå stova si!',
        17: 'Millom forhall og altar skal dei gråta prestarne, Herrens tenarar, og segja: «Spar, Herre, folket ditt, og ikkje du gjere din eigen lyd til eit spottord, til eit ordtak millom folki! Kvi skal dei segja millom folki: «Kvar er deira Gud?»»',
        18: 'Då gløddest Herren upp for sitt land, og han sparde sitt folk.',
        19: 'Herren svara og tala til sitt folk: Sjå, eg vil senda til dykk både korn og saft og olje, so de kann mettast av det. Og ikkje vil eg gjera dykk meir til spott millom folki.',
        20: 'Norderheren driv eg langt burt ifrå dykk. Eg skal støyta honom ut i eit turt og øyde land, hans fortropp til havet i aust, hans baktropp til havet i vest. Og vondt skal det dåma, ja ilt skal det tevja. For storverk hev han gjort.',
        21: 'Ikkje ottast, du land, men gled deg og ver sæl! For storverk hev Herren gjort.',
        22: 'Ikkje ottast, du fe på marki, for no grønast graset på heidi. Og trei ber frukt, fiketre, vintre gjev no si kraft.',
        23: 'Og Sions søner, fagna og frygda dykk i Herren, dykkar Gud! For han gjev åt dykk læraren til rettferd; so sender han dykk haustregn og vårregn som fyrr.',
        24: 'Og fyllast skal låvarne med korn, og persorne fløyma med vinsaft og olje.',
        25: 'Og skadebot gjev eg for grøda som tyntest av grashoppen, bitaren, etaren, gnagaren, min store her, som eg sende imot dykk.',
        26: 'Og de skal få nøgdi eta og mettast. Og då skal de lova namnet åt Herren dykkar Gud, han som hev underleg stelt med dykk, og ikkje skal folket mitt æveleg skjemmast.',
        27: 'Og de skal merka at eg bur midt i Israel, og at eg er Herren, dykkar Gud, og ingen annan, og ikkje skal folket mitt æveleg skjemmast.',
    },
    3: {
        1: 'Og sidan henda det skal: Eg renner min ande yver alt kjøt. Dykkar søner og døtter skal tala profetord; dei gamle hjå dykk skal draumar drøyma, gutarne dykkar skal syner sjå.',
        2: 'Ja, og yver trælar og trælekvende eg renner min ande i dagarne dei.',
        3: 'Under eg gjer på himmel og på jord, blod og eld og kvervlande røyk.',
        4: 'Soli skal verta til myrker og månen til blod, fyrr han kjem, Herrens dag, den store og skræmelege.',
        5: 'Men kvar ein som kallar på Herrens namn, bergast skal han. For på Sions fjell og i Jerusalem skal finnast ein flokk av frelste som Herren hev sagt, og til den utfria flokken høyrer dei som Herren kallar.',
        6: 'For sjå, i dei dagarne og det bilet, då eg vender lagnaden for Juda og Jerusalem,',
        7: 'då vil eg samla alle folki og føra deim ned i Josafatsdalen og der halda dom yver deim for mitt folk og min eignalut Israel skuld, som dei spreidde millom folki, og mitt land hev dei bytt.',
        8: 'Um mitt folk drog dei strå, gav ein gut for ei skjøkja, og ei gjenta selde dei for vin, og so drakk dei.',
        9: 'Og kva vil det meg, Tyrus og Sidon og Filistar-bygder alle? Er det attergjeld mot meg det vil, eller vil de gjera meg eitkvart? Ovleg brått dykkar verk eg vender imot dykk sjølve,',
        10: 'De som sylvet og gullet mitt tok, og eignaluter mine so fagre til dykkar tempel førde.',
        11: 'Og Judas og Jerusalems søner de selde til Javans søner, til å førast so langt burt ifrå sitt land.',
        12: 'Eg ropar deim fram att frå den staden der de hev selt deim. Dykkar verk eg vendar imot dykk sjølve.',
        13: 'Eg skal dykkar søner og døtter til Juda-sønerne selja; derifrå skal dei til sabæarane gå, eit folk so langt undan. For Herren hev tala.',
        14: 'Lat heidningar det høyra! Til herferd vigje dykk! Lat kjemporne koma! Gange fram! Stige fram alle herføre hausar!',
        15: 'Smide plogarne til sverd og hage-knivarne til spjot! Vesaling segje: «Eg er kjempekar eg!»',
        16: 'Skunda dykk og kome, heidningar alle ikring! Samle dykk i hop! Dit late du, Herre, dine kjempor stiga ned.',
        17: 'Lat folki vakna og samlast i Josafatsdalen! For der eg domar sit yver alle folki ikring.',
        18: 'Fram med sigden! No mognast kornet. Kome, trakke! No er persa full. Kjeraldi fløymer. Ovstor er vondska.',
        19: 'Flokk på flokk i domsdalen. For Herrens dag er nær i domsdalen.',
        20: 'Sol og måne dei svartnar, og stjernorne løyner sin glans.',
        21: 'Og Herren burar frå Sion, frå Jerusalem gjallar hans mål. Og det bivrar både himmel og jord. Men Herren er ei livd for sitt folk og ei borg for Israels søner. Ja, kjenna skal de at eg er Herren, dykkar Gud, som bur på Sion, mitt heilage berg. Og Jerusalem skal ein heilagdom vera, frammandfolk der aldri meir stiga inn. Då skal på den dagen druvesafti drjupa av fjelli og mjølk frå haugarne strøyma, og alle bekkjer i Juda fløyma med vatn. Ei kjelda spring ut frå Herrens hus og vatnar Akaziedalen. Men Egypt skal øydeland verta, og Edom som ville heidi, for valdsverk mot Judas born. Dei hev øydt skuldlaust blod i sitt land. Men Juda skal sitja æveleg trygt, og Jerusalem frå ætt til ætt. Og eg vil hemner deira blod, som eg ikkje hemnde fyrr. Og Herren skal bu på Sion.',
    },
}
